   case 'save_settings':$tagline=post_string('site_tagline',250);$notice=post_string('site_notice',700);$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute(['site_tagline',$tagline]);$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute(['site_notice',$notice]);audit($pdo,(int)$admin['id'],'SETTINGS_UPDATED','Public tagline and notice updated');$ok='Site settings saved.';$tab='settings';break;
   case 'test_email':$sent=mail_admin($pdo,$config,'Fortune Apex SMTP test','This is a test message from the Fortune Apex admin console.');if(!$sent)throw new RuntimeException('Test email failed. Check SMTP settings, the Google App Password and hosting error logs.');$ok='Test email sent to the configured admin email.';$tab='settings';break;
   default:throw new RuntimeException('Unknown action.');
  }
  if($replayingApprovalId>0) {
    $pdo->prepare("UPDATE admin_approvals SET status='APPROVED',decision_note='Approved and applied',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='PENDING'")->execute([(int)$admin['id'],$replayingApprovalId]);
    audit($pdo,(int)$admin['id'],'ADMIN_DECISION_APPROVED','Request #'.$replayingApprovalId.' / '.$action.' applied');
    if($pdo->inTransaction()) $pdo->commit();
    $rq=$pdo->prepare('SELECT u.email,u.display_name,a.requested_by FROM admin_approvals a JOIN users u ON u.id=a.requested_by WHERE a.id=?');$rq->execute([$replayingApprovalId]);$requester=$rq->fetch();
    if($requester) { try { send_app_mail($config,$requester['email'],'Fortune Apex admin decision approved',"Hello {$requester['display_name']},\n\nYour admin action request #{$replayingApprovalId} was approved by {$admin['display_name']} and applied.\nAction: {$action}"); } catch(Throwable $mx) { error_log('[Fortune Apex approval mail] Delivery failed (' . get_class($mx) . ', code ' . (string)$mx->getCode() . ').'); } }
  }
  if($ok)flash('success',$ok);redirect('/admin.php?tab='.rawurlencode($tab));
 } catch(Throwable $ex) { if(isset($pdo) && $pdo->inTransaction()) $pdo->rollBack(); if($ex instanceof PDOException && (string)$ex->getCode()==='23000')$error='That code or value already exists. Use a unique code.';elseif($ex instanceof RuntimeException)$error=$ex->getMessage();else{$error='Could not complete that change. Check fields and server logs.';error_log('[Fortune Apex admin] Action failed (' . get_class($ex) . ', code ' . (string)$ex->getCode() . ').');} }
}
