<?php elseif($tab==='approvals'): ?><section class="panel"><div class="section-heading"><div><div class="eyebrow">Two-person control</div><h2>Admin decision handoff</h2><p>Every official admin change is queued for the other admin. Pending requests have not been applied. You can only review requests assigned to your account.</p></div><input class="searchbar" aria-label="Search approvals assigned to you" placeholder="Search by requester, action, status or request ID…" data-search-target="#approvalRows"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Requested by</th><th>Action payload summary</th><th>Status / submitted</th><th>Your decision</th></tr></thead><tbody id="approvalRows"><?php foreach($approvals as $a): $payloadSummary=json_decode((string)$a['payload_json'],true)?:[]; $safeParts=[]; foreach(['title','display_name','code','name','status','category','site_tagline','id','username'] as $sk){if(isset($payloadSummary[$sk]) && is_scalar($payloadSummary[$sk])) $safeParts[]=$sk.': '.substr((string)$payloadSummary[$sk],0,100);} ?><tr data-search-text="<?=e(strtolower($a['requester_name'].' '.$a['requester_username'].' '.$a['action_type'].' '.$a['status'].' '.implode(' ',$safeParts).' '.$a['id']))?>"><td><b>FA-APR-<?=str_pad((string)$a['id'],4,'0',STR_PAD_LEFT)?></b><div class="meta">#<?= (int)$a['id'] ?> · <?=e($a['action_type'])?></div></td><td><?=e($a['requester_name'])?><div class="meta">@<?=e($a['requester_username'])?></div></td><td><?=e(implode(' · ',$safeParts) ?: 'Review the submitted admin change')?></td><td><span class="tag <?=e(strtolower($a['status']))?>"><?=e($a['status'])?></span><div class="meta"><?=e($a['created_at'])?></div><?php if($a['decision_note']!==''): ?><div class="meta"><?=e($a['decision_note'])?></div><?php endif; ?></td><td><?php if($a['status']==='PENDING'): ?><form method="post" class="approval-decision-form"><?=csrf_field()?><input type="hidden" name="action" value="review_approval"><input type="hidden" name="approval_id" value="<?=(int)$a['id']?>"><label class="field">Reason / note<textarea name="decision_note" rows="2" maxlength="1000" placeholder="Optional rejection reason"></textarea></label><button class="btn small gold" name="decision" value="APPROVED" type="submit" data-confirm="Approve and apply this admin action?">Approve & apply</button> <button class="btn small danger" name="decision" value="REJECTED" type="submit" data-confirm="Reject this admin action without applying it?">Reject</button></form><?php else: ?><span class="meta">Reviewed by <?=e($a['reviewer_name']??'admin')?></span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$approvals): ?><div class="empty">Nothing assigned to your admin account yet.</div><?php endif; ?></section>
